using System;
using System.Collections.Generic;
using UnityEngine;

namespace SmartLife.AR
{
    /// <summary>
    /// The printed marker cards this app can track. Generated by tools/markers/generate_markers.py into
    /// Resources/Markers: catalog.json plus one PNG per marker, stored as .bytes so Unity keeps the file
    /// as-is and the image stays readable at runtime. Vuforia builds its Image Targets from these at start,
    /// so no target database download from the Vuforia portal is needed.
    /// </summary>
    public sealed class MarkerCatalog
    {
        public const string ResourceFolder = "Markers";
        public const string CatalogName = "catalog";
        private const int MaxVuforiaPixels = 2048;

        [Serializable]
        private class Data
        {
            [SerializeField] private float printedWidthMeters;
            [SerializeField] private string[] markers = Array.Empty<string>();
            public float PrintedWidthMeters => printedWidthMeters;
            public string[] Markers => markers;
        }

        public float PrintedWidthMeters { get; }
        public IReadOnlyList<string> MarkerIds { get; }

        private MarkerCatalog(float printedWidthMeters, IReadOnlyList<string> markerIds)
        {
            PrintedWidthMeters = printedWidthMeters;
            MarkerIds = markerIds;
        }

        /// <summary>Parses catalog.json. Throws on a missing width, an empty list or a duplicate marker.</summary>
        public static MarkerCatalog Parse(string json)
        {
            Data data = JsonUtility.FromJson<Data>(json);
            if (data == null || data.PrintedWidthMeters <= 0f)
                throw new FormatException("Marker catalog needs a printedWidthMeters above 0.");
            if (data.Markers.Length == 0)
                throw new FormatException("Marker catalog lists no markers.");

            var seen = new HashSet<string>();
            foreach (string id in data.Markers)
                if (string.IsNullOrEmpty(id) || !seen.Add(id))
                    throw new FormatException($"Marker catalog has an empty or duplicate marker id '{id}'.");

            return new MarkerCatalog(data.PrintedWidthMeters, data.Markers);
        }

        /// <summary>Loads the catalog shipped in Resources/Markers, or null if it is missing.</summary>
        public static MarkerCatalog LoadFromResources()
        {
            var file = Resources.Load<TextAsset>($"{ResourceFolder}/{CatalogName}");
            return file == null ? null : Parse(file.text);
        }

        /// <summary>
        /// The marker's card image as an uncompressed RGBA32 texture, the format Vuforia accepts.
        /// Returns null if the image is missing, unreadable or larger than Vuforia supports.
        /// </summary>
        public static Texture2D LoadImage(string markerId)
        {
            var file = Resources.Load<TextAsset>($"{ResourceFolder}/{markerId}");
            if (file == null) return null;

            var texture = new Texture2D(2, 2, TextureFormat.RGBA32, false) { name = markerId };
            if (!texture.LoadImage(file.bytes, false) ||
                texture.width > MaxVuforiaPixels || texture.height > MaxVuforiaPixels)
            {
                Release(texture);
                return null;
            }
            if (texture.format == TextureFormat.RGBA32 || texture.format == TextureFormat.RGB24) return texture;

            // LoadImage may pick another format; Vuforia only takes RGB24 or RGBA32.
            var converted = new Texture2D(texture.width, texture.height, TextureFormat.RGBA32, false) { name = markerId };
            converted.SetPixels32(texture.GetPixels32());
            converted.Apply(false, false);
            Release(texture);
            return converted;
        }

        private static void Release(Texture2D texture)
        {
            if (Application.isPlaying) UnityEngine.Object.Destroy(texture);
            else UnityEngine.Object.DestroyImmediate(texture);
        }
    }
}
